import { Suspense, lazy, useEffect, useState, type FormEvent, type ReactNode } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { Activity, ArrowDownToLine, ArrowLeft, ArrowRight, Bell, Check, CheckCheck, ChevronDown, ChevronRight, CircleAlert, CircleCheck, Clock3, Compass, ExternalLink, Flag, LayoutDashboard, LifeBuoy, LoaderCircle, LockKeyhole, LogOut, Menu, MessageCircle, MessageSquare, Plus, Reply, Search, Send, ShieldCheck, Sparkles, Users, X, ListChecks, Target, CalendarDays, ClipboardList, BarChart3, UserRound } from 'lucide-react';
import { Button } from './components/ui/button';
import { Dialog } from './components/ui/dialog';
import { api, patch, post, setCsrf, type Attention, type Client, type DashboardData, type Mentor, type Message, type Notification, type Program, type Ticket, type User } from './lib/api';
import { Activation, AccessManagement, Programs, FollowupDialog } from './Management';
import { Plans, Tasks, ClientPlans, TaskOverview } from './Plans';
import { Attachments } from './Attachments';
import { Avatar } from './components/Avatar';
import './profile.css';
import { useMotionRegion } from './lib/use-motion-region';
import { navigationMotionKey } from './lib/motion';
import { useMobileNavigation } from './lib/use-mobile-navigation';
import { Meetings, MeetingsOverview, ClientMeetings } from './Meetings';
const Diagnostics = lazy(() => import('./Diagnostics').then(module => ({ default: module.Diagnostics })));
const Indicators = lazy(() => import('./Indicators').then(module => ({ default: module.Indicators })));
const ClientIndicators = lazy(() => import('./Indicators').then(module => ({ default: module.ClientIndicators })));
const ClientDiagnostics = lazy(() => import('./Diagnostics').then(module => ({ default: module.ClientDiagnostics })));
const Reports = lazy(() => import('./Reports').then(module => ({default:module.Reports})));
const Commercial = lazy(() => import('./Commercial').then(module => ({default:module.Commercial})));
const Journey = lazy(() => import('./Journey').then(module => ({default:module.Journey})));
const Materials = lazy(() => import('./Materials').then(module => ({default:module.Materials})));
const Integrations = lazy(() => import('./Integrations').then(module => ({default:module.Integrations})));
const Help = lazy(() => import('./Help').then(module => ({ default: module.Help })));
const Profile = lazy(() => import('./Profile').then(module => ({ default: module.Profile })));

const statusLabels: Record<string, string> = { new: 'Novo', waiting_mentor: 'Aguardando mentor', in_progress: 'Em tratamento', waiting_mentee: 'Aguardando mentorado', resolved: 'Resolvido', reopened: 'Reaberto', active: 'Ativa', paused: 'Pausada', ended: 'Encerrada', closed: 'Encerrada', cancelled: 'Cancelada' };
const stageLabels: Record<string, string> = { onboarding: 'Entrada', diagnosis: 'Diagnóstico', planning: 'Plano de ação', action_plan: 'Plano de ação', execution: 'Execução', review: 'Revisão', renewal: 'Renovação', closure: 'Encerramento' };
const roleLabels = { admin: 'Administração', mentor: 'Mentor', mentee: 'Mentorado' };
const fmtDate = (value?: string) => value ? new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short', timeZone: 'America/Sao_Paulo' }).format(new Date(value)) : 'Não informado';
const fmtTime = (value?: string) => value ? new Intl.DateTimeFormat('pt-BR', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit', timeZone: 'America/Sao_Paulo' }).format(new Date(value)) : 'Sem prazo definido';
const dueAt = (ticket: Ticket) => [ticket.firstResponseDueAt, ticket.nextResponseDueAt, ticket.promisedAt, ticket.resolutionDueAt].filter(Boolean).sort()[0];
const isOverdue = (ticket: Ticket) => ticket.status !== 'resolved' && Boolean(dueAt(ticket) && new Date(dueAt(ticket)!).getTime() < Date.now());

function useRoute() {
  const [route, setRoute] = useState(location.hash.slice(1) || '/dashboard');
  useEffect(() => { const handler = () => setRoute(location.hash.slice(1) || '/dashboard'); window.addEventListener('hashchange', handler); return () => window.removeEventListener('hashchange', handler); }, []);
  const navigate = (to: string) => { location.hash = to; };
  return { route, navigate };
}
function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: string }) { return <span className={`badge ${tone}`}>{children}</span>; }
function ErrorBox({ error }: { error: unknown }) { return error ? <div role="alert" className="error-box"><CircleAlert size={17} /><span>{error instanceof Error ? error.message : String(error)}</span></div> : null; }
function Empty({ title, detail, action }: { title: string; detail?: string; action?: ReactNode }) { return <div className="empty"><div className="empty-icon"><CheckCheck size={25} /></div><h3>{title}</h3>{detail && <p>{detail}</p>}{action}</div>; }
function Loading() { return <div className="loading" role="status"><LoaderCircle className="spin" size={22} /> Carregando informações…</div>; }
function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) { return <label className="field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>; }
function PageTitle({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description: string; action?: ReactNode }) { return <div className="page-title"><div>{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h1>{title}</h1><p>{description}</p></div>{action}</div>; }

export function App() {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [toast, setToast] = useState('');
  const queryClient = useQueryClient();
  useEffect(() => { api<{ user: User; csrfToken: string }>('/auth/me').then(data => { setUser(data.user); setCsrf(data.csrfToken); }).catch(() => {}).finally(() => setLoading(false)); }, []);
  useEffect(() => { if (!toast) return; const timeout = setTimeout(() => setToast(''), 5000); return () => clearTimeout(timeout); }, [toast]);
  const onLogin = (data: { user: User; csrfToken: string }) => { queryClient.clear(); setUser(data.user); setCsrf(data.csrfToken); };
  const logout = async () => { try { await post('/auth/logout', {}); queryClient.clear(); setCsrf(''); setUser(null); } catch { setToast('Não foi possível sair. Tente novamente.'); } };
  if (location.pathname === '/ativar') return <Activation />;
  if (loading) return <div className="boot"><Logo /><Loading /></div>;
  return <>{user ? <Workspace user={user} onUserChange={setUser} logout={logout} notify={setToast} /> : <Login onLogin={onLogin} />}{toast && <div className="toast" role="status"><CircleCheck size={19} />{toast}<button aria-label="Fechar aviso" onClick={() => setToast('')}><X size={16} /></button></div>}</>;
}

function Logo() { return <div className="brand"><span className="brand-symbol"><span /><span /></span><span>elo<span className="brand-dot">.</span><small>MENTORIA</small></span></div>; }

function Login({ onLogin }: { onLogin: (data: { user: User; csrfToken: string }) => void }) {
  const [error, setError] = useState<unknown>();
  const [busy, setBusy] = useState(false);
  const [showOtp, setShowOtp] = useState(false);
  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setBusy(true); setError(null); const values = Object.fromEntries(new FormData(event.currentTarget)); try { onLogin(await post('/auth/login', values)); } catch (err) { setError(err); } finally { setBusy(false); } };
  return <div className="login"><section className="login-story"><Logo /><div className="login-copy"><span className="eyebrow">GENTE PERTO. NEGÓCIOS MAIS LONGE.</span><h1>Crescer é melhor<br />com acompanhamento.</h1><p>Cada conversa importa. Cada próximo passo também. A sua operação de mentoria, conectada de ponta a ponta.</p><div className="login-art"><div className="art-orbit" /><div className="art-card"><span className="art-check"><Check size={18} /></span><div><strong>Presença que faz a diferença</strong><span>Clareza para agir. Tempo para acompanhar.</span></div></div><span className="art-dot one" /><span className="art-dot two" /></div></div><p className="login-footer">Uma plataforma independente para sua operação de mentoria.</p></section><section className="login-form-wrap"><form className="login-form" onSubmit={submit}><div className="mobile-logo"><Logo /></div><span className="welcome-icon"><Compass size={28} /></span><h2>Bom ter você por aqui.</h2><p>Acesse seu espaço de acompanhamento.</p><Field label="E-mail"><input name="email" type="email" autoComplete="username" placeholder="voce@empresa.com.br" required /></Field><Field label="Senha"><input name="password" type="password" autoComplete="current-password" minLength={8} required placeholder="Sua senha" /></Field><button type="button" className="text-button" onClick={() => setShowOtp(!showOtp)}>{showOtp ? 'Ocultar código de autenticação' : 'Usar código de autenticação em duas etapas'}</button>{showOtp && <Field label="Código de autenticação"><input name="otp" inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{6}" maxLength={6} placeholder="000000" /></Field>}<ErrorBox error={error} /><Button size="lg" className="w-full" disabled={busy}>{busy ? <LoaderCircle className="spin" /> : <ArrowRight />}Entrar na plataforma</Button><p className="login-help"><LockKeyhole size={14} />Seu acesso respeita sua carteira e suas permissões.</p></form></section></div>;
}

function Workspace({ user, onUserChange, logout, notify }: { user: User; onUserChange: (user: User) => void; logout: () => void; notify: (message: string) => void }) {
  const { route, navigate } = useRoute();
  const pageMotion = useMotionRegion(navigationMotionKey(route), 'page');
  const { mobileOpen, setMobileOpen, mobile } = useMobileNavigation();
  const [globalSearch, setGlobalSearch] = useState('');
  const notifications = useQuery({ queryKey: ['notifications'], queryFn: () => api<Notification[]>('/notifications'), refetchInterval: 30_000 });
  const unread = notifications.data?.filter(n => !n.acknowledgedAt).length || 0;
  const path = route.split('?')[0];
  const active = path.split('/')[1];
  const dashboardTitle = user.role === 'admin' ? 'Visão da operação' : user.role === 'mentor' ? 'Meu dia' : 'Minha evolução';
  const links = [{ id: 'dashboard', label: dashboardTitle, icon: LayoutDashboard }, { id: 'tickets', label: 'Atendimentos', icon: MessageSquare }, { id: 'diagnoses', label: 'Diagnósticos', icon: ClipboardList }, { id: 'indicators', label: 'Indicadores e metas', icon: BarChart3 }, { id: 'plans', label: 'Planos de ação', icon: Target }, { id: 'tasks', label: 'Tarefas', icon: ListChecks }, { id: 'meetings', label: 'Reuniões', icon: CalendarDays }, { id: 'journey', label: 'Jornada e relacionamento', icon: Compass }, { id: 'materials', label: 'Materiais', icon: ClipboardList }, ...(user.role !== 'mentee' ? [{ id: 'reports', label: 'Relatórios gerenciais', icon: BarChart3 }] : []), { id: 'clients', label: user.role === 'mentee' ? 'Minha empresa' : 'Clientes e carteiras', icon: Users }, ...(user.role === 'admin' ? [{ id: 'commercial', label: 'Comercial e financeiro', icon: BarChart3 }, { id: 'integrations', label: 'Integrações', icon: Activity }, { id: 'mentors', label: 'Equipe de mentores', icon: Compass }, { id: 'programs', label: 'Programas e prazos', icon: Clock3 }, { id: 'users', label: 'Usuários e acessos', icon: ShieldCheck }] : []), { id: 'notifications', label: 'Central de alertas', icon: Bell }, { id: 'help', label: 'Central de ajuda', icon: LifeBuoy }, { id: 'profile', label: 'Meu perfil', icon: UserRound }];
  const go = (to: string) => { navigate(to); setMobileOpen(false); };
  return <div className="workspace"><a className="skip-link" href="#main" onClick={e => { e.preventDefault(); document.getElementById('main')?.focus(); }}>Ir para o conteúdo</a><button className={`mobile-scrim ${mobileOpen ? 'open' : ''}`} aria-label="Fechar navegação" aria-hidden={!mobileOpen} tabIndex={-1} onClick={() => setMobileOpen(false)} /><aside id="workspace-navigation" inert={mobile && !mobileOpen} role={mobile && mobileOpen ? 'dialog' : undefined} aria-modal={mobile && mobileOpen ? true : undefined} aria-label="Navegação da plataforma" className={`sidebar ${mobileOpen ? 'open' : ''}`}><Logo /><div className="organization"><span className="organization-icon">M</span><div><strong>Minha mentoria</strong><span>Espaço de trabalho</span></div><ChevronDown size={14} /></div><span className="nav-caption">ACOMPANHAMENTO</span><nav>{links.map(link => <button key={link.id} onClick={() => go(`/${link.id}`)} className={active === link.id ? 'active' : ''}><link.icon size={19} /><span>{link.label}</span>{link.id === 'notifications' && unread > 0 && <span className="nav-count">{unread}</span>}</button>)}</nav><div className="sidebar-note"><span className="note-icon"><Sparkles size={18} /></span><strong>Proximidade gera evolução.</strong><p>Um pequeno acompanhamento pode destravar um grande próximo passo.</p></div><div className="sidebar-bottom"><span><ShieldCheck size={16} />Acesso protegido</span><div className="profile"><button className="profile-open" aria-label="Abrir meu perfil" onClick={() => go('/profile')}><Avatar name={user.name} src={user.avatarUrl} /><div><strong>{user.name}</strong><span>{roleLabels[user.role]}</span></div></button><button aria-label="Sair da plataforma" title="Sair da plataforma" onClick={logout}><LogOut size={18} /></button></div></div></aside><div className="main-wrap" inert={mobile && mobileOpen}><header className="topbar"><button className="mobile-menu icon-button" onClick={() => setMobileOpen(true)} aria-label="Abrir navegação" aria-expanded={mobileOpen} aria-controls="workspace-navigation"><Menu size={22} /></button><div className="breadcrumb">Seu espaço <ChevronRight size={13} /><strong>{links.find(l => l.id === active)?.label || 'Acompanhamento'}</strong></div><div className="topbar-actions"><form className="global-search" onSubmit={e => { e.preventDefault(); go(`/tickets?q=${encodeURIComponent(globalSearch)}`); }}><Search size={16} /><input aria-label="Buscar atendimentos" placeholder="Buscar atendimentos…" value={globalSearch} onChange={e => setGlobalSearch(e.target.value)} /></form><button className="icon-button" aria-label="Abrir Central de ajuda" title="Central de ajuda" onClick={() => go('/help')}><LifeBuoy size={20} /></button><button className="notification-button icon-button" aria-label={`Alertas: ${unread} não lidos`} onClick={() => go('/notifications')}><Bell size={20} />{unread > 0 && <span />}</button><button className="profile-avatar-button" aria-label={`Perfil de ${user.name}`} title="Meu perfil" onClick={() => go('/profile')}><Avatar name={user.name} src={user.avatarUrl} small /></button></div></header><main ref={pageMotion} id="main" tabIndex={-1} className="main-content">
    {active === 'profile' && <Suspense fallback={<Loading />}><Profile user={user} onUserChange={onUserChange} notify={notify} /></Suspense>}
    {active === 'help' && <Suspense fallback={<Loading />}><Help route={route} user={user} go={go} notify={notify} /></Suspense>}
    {active === 'dashboard' && <Dashboard user={user} title={dashboardTitle} go={go} />}
    {active === 'tickets' && (path.split('/')[2] ? <TicketDetail id={path.split('/')[2]} user={user} go={go} notify={notify} /> : <Tickets user={user} route={route} go={go} notify={notify} />)}
    {active === 'clients' && (path.split('/')[2] ? <ClientDetail id={path.split('/')[2]} user={user} go={go} notify={notify} /> : <Clients user={user} route={route} go={go} notify={notify} />)}
    {active === 'diagnoses' && <Suspense fallback={<Loading />}><Diagnostics route={route} user={user} go={go} notify={notify} /></Suspense>}
    {active === 'indicators' && <Suspense fallback={<Loading />}><Indicators route={route} user={user} go={go} notify={notify} /></Suspense>}
    {active === 'reports' && <Suspense fallback={<Loading />}><Reports route={route} user={user} go={go} notify={notify}/></Suspense>}
    {active === 'commercial' && user.role === 'admin' && <Suspense fallback={<Loading />}><Commercial route={route} user={user} go={go} notify={notify}/></Suspense>}
    {active === 'journey' && <Suspense fallback={<Loading />}><Journey route={route} user={user} go={go} notify={notify}/></Suspense>}
    {active === 'materials' && <Suspense fallback={<Loading />}><Materials route={route} user={user} go={go} notify={notify}/></Suspense>}
    {active === 'integrations' && user.role === 'admin' && <Suspense fallback={<Loading />}><Integrations route={route} user={user} go={go} notify={notify}/></Suspense>}
    {active === 'plans' && <Plans route={route} user={user} go={go} notify={notify} />}
    {active === 'tasks' && <Tasks route={route} user={user} go={go} notify={notify} />}
    {active === 'meetings' && <Meetings route={route} user={user} go={go} notify={notify} />}
    {active === 'mentors' && user.role === 'admin' && <Mentors />}
    {active === 'programs' && user.role === 'admin' && <Programs notify={notify} />}
    {active === 'users' && user.role === 'admin' && <AccessManagement currentUser={user} notify={notify} />}
    {active === 'notifications' && <Notifications data={notifications.data} error={notifications.error} loading={notifications.isPending} go={go} notify={notify} />}
    {((['commercial','integrations','mentors','programs','users'].includes(active)&&user.role!=='admin')||!['dashboard', 'tickets', 'clients', 'mentors', 'notifications', 'programs', 'users', 'plans', 'tasks', 'meetings', 'diagnoses', 'indicators','reports','commercial','journey','materials','integrations','help','profile'].includes(active)) && <Empty title="Página indisponível para este acesso" action={<Button onClick={() => go('/dashboard')}>Voltar ao início</Button>} />}
  </main><footer className="app-footer"><span>Elo • Gestão de mentoria</span><span>Horários de Brasília · America/Sao_Paulo</span></footer></div></div>;
}

function Dashboard({ user, title, go }: { user: User; title: string; go: (to: string) => void }) {
  const query = useQuery({ queryKey: ['dashboard'], queryFn: () => api<DashboardData>('/dashboard'), refetchInterval: 30_000 });
  const [attentionFilter, setAttentionFilter] = useState('all');
  const attentionMotion = useMotionRegion(attentionFilter);
  const data = query.data;
  const today = new Intl.DateTimeFormat('pt-BR', { weekday: 'long', day: 'numeric', month: 'long', timeZone: 'America/Sao_Paulo' }).format(new Date());
  return <><PageTitle eyebrow="ACOMPANHAMENTO COM PROPÓSITO" title={title} description={`Olá, ${user.name.split(' ')[0]}. ${user.role === 'mentee' ? 'Vamos dar o próximo passo na sua jornada?' : 'Um olhar atento para quem precisa de você.'}`} action={<span className="date-chip"><span />{today}</span>} /><ErrorBox error={query.error} />{query.isPending ? <Loading /> : data && <>
    <section className="overview-banner"><div><div className="banner-kicker"><Activity size={16} />O QUE IMPORTA AGORA</div><h2>{data.attention.length ? `${data.attention.length} ${data.attention.length === 1 ? 'ponto merece' : 'pontos merecem'} a sua atenção.` : 'Espaço para acompanhar de perto.'}</h2><p>{data.attention.length ? 'Reúna contexto, defina o próximo passo e mantenha a conversa em movimento.' : 'Consulte sua carteira e mantenha os próximos passos combinados.'}</p><Button variant="secondary" onClick={() => document.getElementById('attention')?.scrollIntoView({ behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' })}>Ver prioridades <ArrowRight /></Button></div><div className="banner-graphic" aria-hidden="true"><div className="graphic-orbit" /><span className="graphic-bubble big"><MessageCircle size={38} strokeWidth={1.4} /></span><span className="graphic-bubble little"><Check size={24} /></span><span className="graphic-star">✦</span></div></section>
    <div className="stats-grid"><Stat icon={<Users size={19} />} value={data.stats.activeClients} label={user.role === 'mentee' ? 'Contratações ativas' : 'Clientes ativos'} detail="Carteira em acompanhamento" onClick={() => go('/clients')} /><Stat icon={<MessageCircle size={19} />} value={data.stats.waitingTickets} label="Aguardando resposta" detail="Conversas que precisam seguir" tone="amber" onClick={() => go('/tickets?filter=waiting')} /><Stat icon={<Clock3 size={19} />} value={data.stats.overdueTickets} label="Prazo de atendimento vencido" detail="Prioridade para agir agora" tone={data.stats.overdueTickets ? 'red' : 'neutral'} onClick={() => go('/tickets?filter=overdue')} /><Stat icon={<LifeBuoy size={19} />} value={data.stats.unattendedClients} label="Sem contato recente" detail="Retome o acompanhamento" tone="blue" onClick={() => go('/clients?filter=unattended')} /></div>
    <MeetingsOverview user={user} stats={data.stats} go={go} />
    <TaskOverview user={user} go={go} stats={data.stats} /><button className="indicator-dashboard-link" onClick={() => go('/indicators')}><span><BarChart3 size={21} /></span><div><strong>Indicadores e metas do negócio</strong><p>Consulte os resultados por empresa e mês, com origem e contexto.</p></div><ArrowRight size={18} /></button>
    <div className="dashboard-columns"><section ref={attentionMotion} className="panel attention-panel" id="attention"><div className="panel-heading"><div><h2>Quem precisa de atenção <span className="count-chip">{data.attention.length}</span></h2><p>Sinais claros para uma próxima ação.</p></div><button className="text-button" onClick={() => go('/tickets')}>Ver atendimentos <ArrowRight size={14} /></button></div><div className="tabs"><button className={attentionFilter === 'all' ? 'selected' : ''} onClick={() => setAttentionFilter('all')}>Todas as prioridades</button><button className={attentionFilter === 'tickets' ? 'selected' : ''} onClick={() => setAttentionFilter('tickets')}>Atendimento</button><button className={attentionFilter === 'portfolio' ? 'selected' : ''} onClick={() => setAttentionFilter('portfolio')}>Acompanhamento</button></div><div className="attention-list">{data.attention.filter(a => attentionFilter === 'all' || (attentionFilter === 'tickets' ? !!a.ticketId : !a.ticketId)).map(a => <AttentionRow item={a} key={a.id} go={go} />)}{!data.attention.filter(a => attentionFilter === 'all' || (attentionFilter === 'tickets' ? !!a.ticketId : !a.ticketId)).length && <Empty title="Nenhuma pendência neste filtro" detail="Os sinais de atenção aparecem aqui conforme a operação evolui." />}</div></section>
    <aside className="dashboard-aside"><section className="panel portfolio-summary"><div className="panel-heading"><div><h2>Sua carteira, de perto</h2><p>Pessoas por trás dos números.</p></div><Users size={19} /></div>{data.portfolio.slice(0, 4).map(client => <button className="portfolio-item" key={client.enrollmentId} onClick={() => go(`/clients/${client.id}`)}><Avatar name={client.name} small /><span><strong>{client.name}</strong><small>{client.mentorName || 'Atribuição pendente'}</small></span><ChevronRight size={15} /></button>)}{!data.portfolio.length && <p className="small-empty">Sua carteira ainda não possui clientes.</p>}<button className="panel-bottom-link" onClick={() => go('/clients')}>Abrir carteira <ArrowRight size={15} /></button></section><section className="routine-card"><span className="routine-icon"><Compass size={22} /></span><span className="eyebrow">UM PASSO DE CADA VEZ</span><h3>Acompanhamento é presença.</h3><p>Uma dúvida respondida e um retorno cumprido constroem a confiança para o próximo passo.</p><div><Check size={16} /> Responda às pendências mais antigas</div><div><Check size={16} /> Cumpra os retornos combinados</div><div><Check size={16} /> Retome os contatos pendentes</div></section></aside></div>
  </>}</>;
}
function Stat({ icon, value, label, detail, tone = 'neutral', onClick }: { icon: ReactNode; value: number; label: string; detail: string; tone?: string; onClick: () => void }) { return <button className={`stat-card ${tone}`} onClick={onClick}><div className="stat-top"><span>{icon}</span><ArrowRight size={16} /></div><strong className="stat-number">{value ?? '—'}</strong><span className="stat-label">{label}</span><span className="stat-detail">{detail}</span></button>; }
function AttentionRow({ item, go }: { item: Attention; go: (to: string) => void }) { const urgent = ['critical', 'high', 'danger', 'overdue'].includes(item.severity); return <button className="attention-row" onClick={() => go(item.actionUrl?.startsWith('/') && !item.actionUrl.startsWith('//') ? item.actionUrl : item.meetingId ? `/meetings/${item.meetingId}` : item.taskId ? `/tasks/${item.taskId}` : item.planId ? `/plans/${item.planId}` : item.ticketId ? `/tickets/${item.ticketId}` : `/clients/${item.clientId}`)}><span className={`attention-icon ${urgent ? 'danger' : ''}`}>{item.meetingId ? <CalendarDays size={18} /> : item.taskId ? <ListChecks size={18} /> : item.planId ? <Target size={18} /> : item.ticketId ? <MessageSquare size={18} /> : <Users size={18} />}</span><div className="attention-main"><strong>{item.clientName}</strong><span>{item.reason}</span><small>{item.mentorName || 'Sem mentor responsável'}{item.dueAt && <> · {fmtTime(item.dueAt)}</>}</small></div><Badge tone={urgent ? 'red' : 'amber'}>{urgent ? 'Prioridade' : 'Acompanhar'}</Badge><ChevronRight size={17} /></button>; }

function Tickets({ user, route, go, notify }: { user: User; route: string; go: (to: string) => void; notify: (message: string) => void }) {
  const params = new URLSearchParams(route.split('?')[1]);
  const [search, setSearch] = useState(params.get('q') || '');
  const [filter, setFilter] = useState(params.get('filter') || 'open');
  const [priority, setPriority] = useState('all');
  const [newTicket, setNewTicket] = useState(false);
  const query = useQuery({ queryKey: ['tickets'], queryFn: () => api<Ticket[]>('/tickets'), refetchInterval: 30_000 });
  useEffect(() => { const p = new URLSearchParams(route.split('?')[1]); setSearch(p.get('q') || ''); setFilter(p.get('filter') || 'open'); }, [route]);
  const tickets = (query.data || []).filter(t => `${t.subject} ${t.clientName}`.toLocaleLowerCase('pt-BR').includes(search.toLocaleLowerCase('pt-BR'))).filter(t => priority === 'all' || t.priority === priority).filter(t => filter === 'all' || (filter === 'open' ? t.status !== 'resolved' : filter === 'overdue' ? isOverdue(t) : filter === 'waiting' ? t.unansweredCount > 0 : t.status === filter));
  return <><PageTitle eyebrow="CONVERSAS QUE FAZEM AVANÇAR" title="Central de atendimento" description="Cada dúvida com um responsável. Cada retorno com um prazo." action={<Button onClick={() => setNewTicket(true)}><Plus />Novo atendimento</Button>} /><section className="panel"><div className="filter-bar"><div className="search-field"><Search size={17} /><input aria-label="Buscar cliente ou assunto" placeholder="Buscar cliente ou assunto…" value={search} onChange={e => setSearch(e.target.value)} /></div><select aria-label="Filtrar situação" value={filter} onChange={e => setFilter(e.target.value)}><option value="open">Em aberto</option><option value="all">Todas as situações</option><option value="waiting">Aguardando resposta</option><option value="overdue">Prazo vencido</option>{Object.entries(statusLabels).filter(([k]) => ['new', 'waiting_mentor', 'in_progress', 'waiting_mentee', 'resolved', 'reopened'].includes(k)).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select><select aria-label="Filtrar prioridade" value={priority} onChange={e => setPriority(e.target.value)}><option value="all">Todas as prioridades</option><option value="standard">Padrão</option><option value="urgent">Urgente</option></select></div><ErrorBox error={query.error} />{query.isPending ? <Loading /> : <><div className="list-counter">{tickets.length} {tickets.length === 1 ? 'atendimento encontrado' : 'atendimentos encontrados'}</div><div className="ticket-list">{tickets.map(ticket => <button className="ticket-row" onClick={() => go(`/tickets/${ticket.id}`)} key={ticket.id}><Avatar name={ticket.clientName} /><div className="ticket-main"><span className="ticket-client">{ticket.clientName}</span><strong>{ticket.subject}</strong><small>{ticket.mentorName || 'Sem mentor responsável'} · Aberto em {fmtDate(ticket.createdAt)}</small></div><div className="ticket-tags"><Badge tone={ticket.status === 'resolved' ? 'green' : ticket.status === 'waiting_mentee' ? 'neutral' : 'blue'}>{statusLabels[ticket.status] || ticket.status}</Badge>{ticket.priority === 'urgent' && <Badge tone="amber"><Flag size={11} />Urgente</Badge>}</div><div className={`ticket-due ${isOverdue(ticket) ? 'overdue' : ''}`}><span><Clock3 size={13} />{isOverdue(ticket) ? 'Prazo vencido' : ticket.status === 'resolved' ? 'Concluído' : 'Próximo retorno'}</span><strong>{ticket.status === 'resolved' ? 'Assunto resolvido' : fmtTime(dueAt(ticket))}</strong></div><ChevronRight size={18} /></button>)}</div>{!tickets.length && <Empty title="Nenhum atendimento neste filtro" detail="Ajuste os filtros ou inicie uma nova conversa." action={<Button variant="outline" onClick={() => setNewTicket(true)}><Plus />Novo atendimento</Button>} />}</>}</section><NewTicketDialog open={newTicket} setOpen={setNewTicket} go={go} notify={notify} user={user} /></>;
}

function NewTicketDialog({ open, setOpen, go, notify, enrollmentId }: { open: boolean; setOpen: (open: boolean) => void; go: (to: string) => void; notify: (message: string) => void; user: User; enrollmentId?: string }) {
  const clients = useQuery({ queryKey: ['clients'], queryFn: () => api<Client[]>('/clients'), enabled: open });
  const [error, setError] = useState<unknown>();
  const [busy, setBusy] = useState(false);
  const queryClient = useQueryClient();
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setError(null); setBusy(true); try { const ticket = await post<Ticket>('/tickets', Object.fromEntries(new FormData(event.currentTarget))); await queryClient.invalidateQueries(); setOpen(false); notify('Atendimento aberto. A conversa já está na fila do responsável.'); go(`/tickets/${ticket.id}`); } catch (err) { setError(err); } finally { setBusy(false); } }
  return <Dialog open={open} onOpenChange={setOpen} title="Novo atendimento" description="Conte o que precisa de atenção para dar o próximo passo."><form onSubmit={submit} className="form-stack"><Field label="Cliente / contratação"><select name="enrollmentId" defaultValue={enrollmentId || ''} required><option value="" disabled>Selecione uma contratação</option>{clients.data?.filter(c => c.status === 'active').map(c => <option key={c.enrollmentId} value={c.enrollmentId}>{c.name} · {c.programName}</option>)}</select></Field><Field label="Assunto"><input name="subject" required minLength={3} maxLength={180} placeholder="Ex.: Revisão de preço do novo catálogo" /></Field><Field label="Como podemos ajudar?"><textarea name="description" required minLength={3} maxLength={10000} rows={5} placeholder="Descreva a dúvida e o contexto…" /></Field><Field label="Prioridade"><select name="priority"><option value="standard">Padrão</option><option value="urgent">Urgente</option></select></Field><ErrorBox error={error || clients.error} /><div className="dialog-actions"><Button type="button" variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={busy || clients.isPending}>{busy && <LoaderCircle className="spin" />}Abrir atendimento</Button></div></form></Dialog>;
}

function TicketDetail({ id, user, go, notify }: { id: string; user: User; go: (to: string) => void; notify: (message: string) => void }) {
  const queryClient = useQueryClient();
  const query = useQuery({ queryKey: ['ticket', id], queryFn: () => api<Ticket>(`/tickets/${id}`), refetchInterval: 15_000 });
  const ticket = query.data;
  const [body, setBody] = useState('');
  const [kind, setKind] = useState('public');
  const composerMotion = useMotionRegion(kind);
  const [replyTo, setReplyTo] = useState<Message | null>(null);
  const [promisedAt, setPromisedAt] = useState('');
  const [showPromise, setShowPromise] = useState(false); const [completePromise, setCompletePromise] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<unknown>();
  const [action, setAction] = useState('');
  const draftKey = `elo:draft:${user.id}:${id}`;
  useEffect(() => { const saved = localStorage.getItem(draftKey); let draft = { body: '', kind: 'public' }; if (saved) { try { const parsed = JSON.parse(saved); draft = { body: String(parsed.body || ''), kind: parsed.kind === 'internal' && user.role !== 'mentee' ? 'internal' : 'public' }; } catch { draft = { body: saved, kind: user.role === 'mentee' ? 'public' : 'internal' }; } } setBody(draft.body); setKind(draft.kind); setReplyTo(null); setPromisedAt(''); setCompletePromise(false); }, [draftKey, user.role]);
  const editBody = (value: string) => { setBody(value); localStorage.setItem(draftKey, JSON.stringify({ body: value, kind })); }; const editKind = (value: string) => { setKind(value); localStorage.setItem(draftKey, JSON.stringify({ body, kind: value })); };
  async function send(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); setError(null); try { await post(`/tickets/${id}/messages`, { body, kind, ...(completePromise && kind === 'public' ? { completePromise: true } : {}), ...(replyTo ? { replyToId: replyTo.id } : {}), ...(promisedAt && kind === 'public' ? { promisedAt: new Date(promisedAt).toISOString() } : {}) }); editBody(''); setReplyTo(null); setPromisedAt(''); setShowPromise(false); setCompletePromise(false); await queryClient.invalidateQueries(); notify(kind === 'internal' ? 'Nota interna registrada.' : 'Mensagem enviada.'); } catch (err) { setError(err); } finally { setBusy(false); } }
  async function simpleStatus(status: string) { setBusy(true); setError(null); try { await patch(`/tickets/${id}`, { status }); await queryClient.invalidateQueries(); notify('Situação do atendimento atualizada.'); } catch (err) { setError(err); } finally { setBusy(false); } }
  if (query.isPending) return <Loading />;
  if (query.isError || !ticket) return <ErrorBox error={query.error} />;
  const staff = user.role !== 'mentee';
  return <><button className="back-link" onClick={() => go('/tickets')}><ArrowLeft size={16} />Voltar aos atendimentos</button><PageTitle eyebrow={ticket.clientName} title={ticket.subject} description={`Aberto em ${fmtTime(ticket.createdAt)} · ${ticket.mentorName || 'Sem mentor responsável'}`} action={<Badge tone={ticket.status === 'resolved' ? 'green' : 'blue'}>{statusLabels[ticket.status]}</Badge>} /><div className="conversation-layout"><section className="panel conversation"><div className="conversation-header"><span><MessageSquare size={18} />Histórico da conversa</span><Badge tone={ticket.priority === 'urgent' ? 'amber' : 'neutral'}>{ticket.priority === 'urgent' ? 'Prioridade urgente' : 'Prioridade padrão'}</Badge></div><div className="messages">{ticket.messages?.map(message => <div key={message.id} className={`message ${message.kind === 'internal' ? 'internal' : ''} ${['automatic', 'event'].includes(message.kind) ? 'event' : ''} ${message.authorRole === 'mentee' ? 'from-client' : ''}`}><div className="message-meta"><Avatar name={message.authorName || 'Sistema'} small /><strong>{message.authorName || 'Sistema'}</strong><Badge tone={message.kind === 'internal' ? 'amber' : 'neutral'}>{message.kind === 'internal' ? 'Nota interna' : message.kind === 'automatic' ? 'Resposta automática' : message.kind === 'event' ? 'Evento' : message.authorRole === 'mentee' ? 'Mentorado' : 'Equipe'}</Badge><time>{fmtTime(message.createdAt)}</time></div>{message.replyToId && <div className="reply-reference"><Reply size={13} />Em resposta a: {ticket.messages?.find(m => m.id === message.replyToId)?.body.slice(0, 140) || 'mensagem anterior'}</div>}<p>{message.body}</p>{['public', 'internal'].includes(message.kind) && <Attachments scope={{ kind: 'ticket', id: ticket.id, messageId: message.id }} canUpload={ticket.status !== 'resolved' && message.authorId === user.id && (message.kind === 'public' || user.role !== 'mentee')} internal={message.kind === 'internal'} notify={notify} />}{message.kind === 'internal' && <small className="internal-caption"><LockKeyhole size={12} />Visível somente para a equipe autorizada</small>}{message.kind === 'public' && ticket.status !== 'resolved' && <button className="reply-button" onClick={() => { setReplyTo(message); document.getElementById('message-body')?.focus(); }}><Reply size={13} />Responder a esta mensagem</button>}</div>)}</div><ErrorBox error={error} />{ticket.status !== 'resolved' ? <form ref={composerMotion} className={`composer ${kind === 'internal' ? 'internal-composer' : ''}`} onSubmit={send}><div className="composer-toolbar"><div className="composer-tabs"><button type="button" className={kind === 'public' ? 'selected' : ''} onClick={() => editKind('public')}><MessageCircle size={14} />Mensagem pública</button>{staff && <button type="button" className={kind === 'internal' ? 'selected' : ''} onClick={() => { editKind('internal'); setReplyTo(null); }}><LockKeyhole size={14} />Nota interna</button>}</div><span>Rascunho salvo neste dispositivo</span></div>{kind === 'internal' && <p className="internal-warning">Esta nota é interna. O mentorado não receberá seu conteúdo.</p>}{replyTo && <div className="reply-preview"><Reply size={15} /><span><strong>Respondendo a {replyTo.authorName}</strong>{replyTo.body.slice(0, 160)}</span><button type="button" aria-label="Remover vínculo da resposta" onClick={() => setReplyTo(null)}><X size={15} /></button></div>}<textarea id="message-body" aria-label={kind === 'internal' ? 'Conteúdo da nota interna' : 'Sua mensagem'} value={body} onChange={e => editBody(e.target.value)} rows={4} placeholder={kind === 'internal' ? 'Registre um contexto para a equipe…' : 'Escreva uma resposta com clareza e próximos passos…'} required minLength={1} maxLength={10000} /><p className="composer-attachment-hint">Para anexar um arquivo, envie a mensagem e use “Adicionar arquivo” no histórico.</p>{staff && showPromise && kind === 'public' && <Field label="Retorno prometido (horário deste dispositivo)"><input type="datetime-local" value={promisedAt} onChange={e => setPromisedAt(e.target.value)} required /></Field>}{staff && ticket.promisedAt && kind === 'public' && <label className="checkbox-field"><input type="checkbox" checked={completePromise} onChange={e => setCompletePromise(e.target.checked)} />Esta mensagem cumpre o retorno prometido</label>}<div className="composer-bottom">{staff && kind === 'public' ? <button className="text-button" type="button" onClick={() => { setShowPromise(!showPromise); setPromisedAt(''); }}><Clock3 size={15} />{showPromise ? 'Remover compromisso' : 'Combinar um prazo de retorno'}</button> : <span /> }<Button disabled={busy || !body.trim()}><Send />{kind === 'internal' ? 'Salvar nota' : 'Enviar mensagem'}</Button></div></form> : <div className="resolved-box"><CircleCheck size={24} /><div><strong>Este assunto foi resolvido.</strong><p>Se ainda precisar de ajuda, você pode reabrir a conversa.</p></div><Button variant="outline" onClick={() => simpleStatus('reopened')} disabled={busy}>Reabrir assunto</Button></div>}</section><aside className="ticket-sidebar"><section className="panel details-card"><h3>Combinados do atendimento</h3><div className={`due-highlight ${isOverdue(ticket) ? 'overdue' : ''}`}><Clock3 size={21} /><div><span>{isOverdue(ticket) ? 'Retorno em atraso' : 'Próximo retorno'}</span><strong>{fmtTime(dueAt(ticket))}</strong></div></div><dl><dt>Responsável</dt><dd>{ticket.mentorName || 'Atribuição pendente'}</dd><dt>Dúvidas sem resposta vinculada</dt><dd>{ticket.unansweredCount ?? 'Não informado'}</dd><dt>Resolução prevista</dt><dd>{fmtTime(ticket.resolutionDueAt)}</dd>{ticket.promisedAt && <><dt>Atualização prometida</dt><dd>{fmtTime(ticket.promisedAt)}</dd></>}</dl><button className="text-button" onClick={() => go(`/clients/${ticket.clientId}`)}>Abrir perfil do cliente <ExternalLink size={13} /></button></section>{staff && ticket.status !== 'resolved' && <section className="panel details-card"><h3>Próximo passo</h3><p className="muted">Mantenha a situação alinhada ao que foi combinado.</p><div className="status-actions"><Button variant="outline" disabled={busy || ticket.status === 'in_progress'} onClick={() => simpleStatus('in_progress')}><Activity />Em tratamento</Button><Button variant="outline" onClick={() => setAction('waiting_mentee')}><MessageCircle />Aguardar mentorado</Button><Button onClick={() => setAction('resolved')}><CheckCheck />Resolver atendimento</Button></div></section>}<div className="context-note"><ShieldCheck size={18} /><p>Respostas automáticas e notas internas não cumprem o prazo de resposta humana.</p></div></aside></div><StatusDialog user={user} action={action} setAction={setAction} ticket={ticket} notify={notify} /></>;
}

function StatusDialog({ user, action, setAction, ticket, notify }: { user: User; action: string; setAction: (value: string) => void; ticket: Ticket; notify: (value: string) => void }) {
  const [error, setError] = useState<unknown>(); const [busy, setBusy] = useState(false); const queryClient = useQueryClient();
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setError(null); setBusy(true); try { await patch(`/tickets/${ticket.id}`, { status: action, ...Object.fromEntries(new FormData(event.currentTarget)) }); await queryClient.invalidateQueries(); setAction(''); notify('Situação atualizada e registrada no histórico.'); } catch (err) { setError(err); } finally { setBusy(false); } }
  return <Dialog open={!!action} onOpenChange={open => { if (!open) { setAction(''); setError(null); } }} title={action === 'resolved' ? 'Resolver atendimento' : 'Aguardar o mentorado'} description={action === 'resolved' ? 'Registre a solução para manter o histórico claro.' : 'Vincule a pergunta pública que depende de resposta do mentorado.'}><form className="form-stack" onSubmit={submit}>{action === 'resolved' ? <Field label="Resumo da solução"><textarea name="summary" rows={4} minLength={3} maxLength={4000} required placeholder="O que foi resolvido e quais os próximos passos?" /></Field> : <Field label="Pergunta ou solicitação enviada"><select name="questionMessageId" required><option value="">Selecione uma pergunta pública enviada por você</option>{ticket.messages?.filter(m => m.kind === 'public' && m.authorId === user.id).map(m => <option key={m.id} value={m.id}>{m.body.slice(0, 130)}</option>)}</select></Field>}<ErrorBox error={error} /><div className="dialog-actions"><Button variant="outline" type="button" onClick={() => setAction('')}>Cancelar</Button><Button disabled={busy}>Confirmar</Button></div></form></Dialog>;
}

function Clients({ user, route, go, notify }: { user: User; route: string; go: (to: string) => void; notify: (message: string) => void }) {
  const query = useQuery({ queryKey: ['clients'], queryFn: () => api<Client[]>('/clients') });
  const [search, setSearch] = useState(''); const [newClient, setNewClient] = useState(false);
  const filter = new URLSearchParams(route.split('?')[1]).get('filter');
  const clients = (query.data || []).filter(c => `${c.name} ${c.contactName || ''}`.toLowerCase().includes(search.toLowerCase())).filter(c => filter !== 'unattended' || c.attentionReasons.includes('Sem acompanhamento recente'));
  return <><PageTitle eyebrow="CADA NEGÓCIO, UMA JORNADA" title={user.role === 'mentee' ? 'Minha empresa' : 'Clientes e carteiras'} description="Contexto, responsabilidade e proximidade em um só lugar." action={user.role === 'admin' && <Button onClick={() => setNewClient(true)}><Plus />Adicionar cliente</Button>} /><section className="panel"><div className="filter-bar"><div className="search-field"><Search size={17} /><input aria-label="Buscar cliente" value={search} onChange={e => setSearch(e.target.value)} placeholder="Buscar empresa ou contato…" /></div>{filter === 'unattended' && <Button variant="outline" size="sm" onClick={() => go('/clients')}>Sem acompanhamento recente <X /></Button>}<Button variant="outline" size="sm" asChild><a href="/api/clients/export" download><ArrowDownToLine />Exportar CSV</a></Button><span className="muted">{clients.length} {clients.length === 1 ? 'contratação' : 'contratações'}</span></div><ErrorBox error={query.error} />{query.isPending ? <Loading /> : clients.length ? <div className="table-scroll"><table><thead><tr><th>Cliente</th><th>Programa e etapa</th><th>Responsável</th><th>Acompanhamento</th><th /></tr></thead><tbody>{clients.map(client => <tr key={client.enrollmentId}><td><button className="table-client" onClick={() => go(`/clients/${client.id}`)}><Avatar name={client.name} /><span><strong>{client.name}</strong><small>{client.contactName || 'Contato não informado'}</small></span></button></td><td><strong className="cell-title">{client.programName}</strong><small>{stageLabels[client.stage] || client.stage}</small></td><td>{client.mentorName ? <span className="mentor-cell"><Avatar name={client.mentorName} small />{client.mentorName}</span> : <Badge tone="amber">Sem mentor</Badge>}</td><td><Badge tone={client.attentionReasons?.length ? 'amber' : 'neutral'}>{client.attentionReasons?.length ? `${client.attentionReasons.length} ponto(s) de atenção` : 'Sem alerta registrado'}</Badge><small>Último contato: {fmtDate(client.lastContactAt)}</small></td><td><Button variant="ghost" size="icon" aria-label={`Abrir ${client.name}`} onClick={() => go(`/clients/${client.id}`)}><ChevronRight /></Button></td></tr>)}</tbody></table></div> : <Empty title="Nenhum cliente encontrado" detail="Os clientes autorizados para o seu perfil aparecem aqui." />}</section><NewClientDialog open={newClient} setOpen={setNewClient} notify={notify} /></>;
}

function NewClientDialog({ open, setOpen, notify }: { open: boolean; setOpen: (open: boolean) => void; notify: (message: string) => void }) {
  const programs = useQuery({ queryKey: ['programs'], queryFn: () => api<Program[]>('/programs'), enabled: open });
  const mentors = useQuery({ queryKey: ['mentors'], queryFn: () => api<Mentor[]>('/mentors'), enabled: open });
  const [busy, setBusy] = useState(false); const [error, setError] = useState<unknown>(); const queryClient = useQueryClient();
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); setError(null); const values = Object.fromEntries(new FormData(event.currentTarget)); if (!values.mentorId) delete values.mentorId; if (values.startsAt) values.startsAt = new Date(String(values.startsAt) + 'T00:00:00-03:00').toISOString(); if (values.endsAt) values.endsAt = new Date(String(values.endsAt) + 'T23:59:59-03:00').toISOString(); try { await post('/clients', values); await queryClient.invalidateQueries(); setOpen(false); notify('Cliente e contratação cadastrados.'); } catch (err) { setError(err); } finally { setBusy(false); } }
  return <Dialog open={open} onOpenChange={setOpen} title="Adicionar cliente" description="Crie o cliente e inicie seu primeiro ciclo de mentoria."><form className="form-stack" onSubmit={submit}><Field label="Nome da empresa"><input name="name" minLength={2} maxLength={150} required placeholder="Ex.: Casa & Cuidado" /></Field><div className="form-grid"><Field label="Pessoa de contato"><input name="contactName" minLength={2} required /></Field><Field label="E-mail de contato"><input name="email" type="email" required /></Field></div><Field label="Programa de mentoria"><select name="programId" required><option value="">Selecione o programa</option>{programs.data?.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Mentor principal" hint="Sem atribuição, o cliente será sinalizado para a administração."><select name="mentorId"><option value="">Atribuir depois</option>{mentors.data?.map(m => <option key={m.id} value={m.id}>{m.name} · {m.activeClients}/{m.capacity} clientes</option>)}</select></Field><div className="form-grid"><Field label="Início da contratação"><input name="startsAt" type="date" required /></Field><Field label="Fim da contratação"><input name="endsAt" type="date" required /></Field></div><ErrorBox error={error || programs.error || mentors.error} /><div className="dialog-actions"><Button type="button" variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={busy}>Cadastrar cliente</Button></div></form></Dialog>;
}

type ClientFull = Client & { tickets: Ticket[]; assignments: { id: string; mentorName: string; kind: string; startsAt: string; endsAt?: string }[]; timeline: { id: string; title?: string; action?: string; body?: string; createdAt: string; actorName?: string; details?: {summary?: string; nextStep?: string; body?: string; reviewAt?: string} }[] };
function ClientDetail({ id, user, go, notify }: { id: string; user: User; go: (to: string) => void; notify: (message: string) => void }) {
  const query = useQuery({ queryKey: ['client', id], queryFn: () => api<ClientFull>(`/clients/${id}`) });
  const [assign, setAssign] = useState(false); const [newTicket, setNewTicket] = useState(false); const [followup, setFollowup] = useState('');
  const client = query.data;
  if (query.isPending) return <Loading />;
  if (!client) return <ErrorBox error={query.error} />;
  return <><button className="back-link" onClick={() => go('/clients')}><ArrowLeft size={16} />Voltar à carteira</button><PageTitle eyebrow="PERFIL DO CLIENTE" title={client.name} description={`${client.contactName || 'Contato não informado'} · ${client.email || 'E-mail não informado'}`} action={<div className="inline-actions">{user.role !== 'mentee' && <Button variant="outline" onClick={() => setFollowup('followup')}><CheckCheck />Registrar acompanhamento</Button>}<Button onClick={() => setNewTicket(true)}><Plus />Abrir atendimento</Button></div>} /><div className="client-next-step"><Compass size={20} /><div><strong>Próximo passo: {client.nextStep || 'Ainda não combinado'}</strong><p>{client.nextStepAt ? fmtTime(client.nextStepAt) : 'Combine uma ação e uma data para manter o acompanhamento.'}</p></div>{user.role === 'admin' && <Button variant="outline" size="sm" onClick={() => setFollowup('intervention')}>Registrar intervenção</Button>}</div><div className="client-summary"><section className="panel summary-card"><span className="eyebrow">PROGRAMA E VIGÊNCIA</span><h3>{client.programName}</h3><p>Até {fmtDate(client.endsAt)}</p><Badge tone={client.status === 'active' ? 'green' : 'neutral'}>{statusLabels[client.status] || client.status}</Badge></section><section className="panel summary-card"><span className="eyebrow">MENTOR RESPONSÁVEL</span><h3>{client.mentorName || 'Atribuição pendente'}</h3><p>Responsabilidade atual da contratação</p>{user.role === 'admin' && <button className="text-button" onClick={() => setAssign(true)}>Gerenciar atribuição <ArrowRight size={14} /></button>}</section><section className="panel summary-card"><span className="eyebrow">ACOMPANHAMENTO</span><h3>{stageLabels[client.stage] || client.stage}</h3><p>Contato relevante: {fmtDate(client.lastContactAt)}</p><Badge tone="blue">Histórico preservado</Badge></section></div>{client.attentionReasons?.length > 0 && <div className="attention-summary"><CircleAlert size={20} /><div><strong>Pontos que merecem atenção</strong>{client.attentionReasons.map((r, i) => <span key={i}>{r}</span>)}</div></div>}<div className="inline-actions" style={{marginBottom:24}}><Button variant="outline" onClick={()=>go(`/journey?enrollmentId=${client.enrollmentId}`)}>Jornada, satisfação e histórico</Button><Button variant="outline" onClick={()=>go(`/materials?enrollmentId=${client.enrollmentId}`)}>Materiais indicados</Button></div><ClientMeetings enrollmentId={client.enrollmentId} user={user} go={go} /><Suspense fallback={<Loading />}><ClientDiagnostics enrollmentId={client.enrollmentId} user={user} go={go} /></Suspense><Suspense fallback={<Loading />}><ClientIndicators enrollmentId={client.enrollmentId} go={go} /></Suspense><ClientPlans enrollmentId={client.enrollmentId} user={user} go={go} /><div className="client-columns"><section className="panel"><div className="panel-heading"><div><h2>Atendimentos</h2><p>Conversas e próximos passos deste cliente.</p></div><MessageSquare size={20} /></div>{client.tickets?.length ? client.tickets.map(t => <button className="client-ticket" key={t.id} onClick={() => go(`/tickets/${t.id}`)}><span><strong>{t.subject}</strong><small>{fmtTime(t.createdAt)}</small></span><Badge tone={t.status === 'resolved' ? 'green' : 'blue'}>{statusLabels[t.status]}</Badge><ChevronRight size={16} /></button>) : <Empty title="Nenhum atendimento registrado" detail="Abra uma conversa para iniciar o acompanhamento." />}</section><section className="panel"><div className="panel-heading"><div><h2>Linha do tempo</h2><p>O caminho construído até aqui.</p></div><Clock3 size={19} /></div><div className="timeline">{client.timeline?.length ? client.timeline.map((event, index) => <div className="timeline-item" key={event.id || index}><span className="timeline-dot" /><div><strong>{event.title || event.action || 'Atualização do acompanhamento'}</strong>{(event.body || event.details?.summary || event.details?.body) && <p>{event.body || event.details?.summary || event.details?.body}</p>}{event.details?.nextStep && <p>Próximo passo: {event.details.nextStep}</p>}<small>{fmtTime(event.createdAt)}{event.actorName ? ` · ${event.actorName}` : ''}</small></div></div>) : <p className="small-empty">Os próximos acontecimentos serão registrados aqui.</p>}</div></section></div>{user.role === 'admin' && <section className="panel assignment-history"><div className="panel-heading"><div><h2>Histórico de responsabilidade</h2><p>Substituições e coberturas preservam a autoria do acompanhamento.</p></div></div>{client.assignments?.length ? <div className="table-scroll"><table><thead><tr><th>Mentor</th><th>Responsabilidade</th><th>Início</th><th>Fim</th></tr></thead><tbody>{client.assignments.map((a, i) => <tr key={a.id || i}><td>{a.mentorName}</td><td><Badge>{a.kind === 'coverage' ? 'Cobertura temporária' : 'Principal'}</Badge></td><td>{fmtTime(a.startsAt)}</td><td>{a.endsAt ? fmtTime(a.endsAt) : 'Vigente'}</td></tr>)}</tbody></table></div> : <p className="small-empty">Nenhum mentor atribuído.</p>}</section>}<FollowupDialog mode={followup} setMode={setFollowup} client={client} user={user} notify={notify} /><AssignDialog open={assign} setOpen={setAssign} client={client} notify={notify} /><NewTicketDialog open={newTicket} setOpen={setNewTicket} user={user} enrollmentId={client.enrollmentId} go={go} notify={notify} /></>;
}

function AssignDialog({ open, setOpen, client, notify }: { open: boolean; setOpen: (open: boolean) => void; client: Client; notify: (message: string) => void }) {
  const mentors = useQuery({ queryKey: ['mentors'], queryFn: () => api<Mentor[]>('/mentors'), enabled: open });
  const [kind, setKind] = useState('primary'); const [busy, setBusy] = useState(false); const [error, setError] = useState<unknown>(); const queryClient = useQueryClient();
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setError(null); setBusy(true); const values = Object.fromEntries(new FormData(event.currentTarget)); if (values.endsAt) values.endsAt = new Date(String(values.endsAt)).toISOString(); try { await post(`/enrollments/${client.enrollmentId}/assignments`, values); await queryClient.invalidateQueries(); setOpen(false); notify('Responsabilidade atualizada. O histórico foi preservado.'); } catch (err) { setError(err); } finally { setBusy(false); } }
  return <Dialog open={open} onOpenChange={setOpen} title="Gerenciar responsabilidade" description={`${client.name} · ${client.programName}`}><form className="form-stack" onSubmit={submit}><Field label="Tipo de atribuição"><select name="kind" value={kind} onChange={e => setKind(e.target.value)}><option value="primary">Mentor principal</option><option value="coverage">Cobertura temporária</option></select></Field><Field label="Mentor"><select name="mentorId" required><option value="">Selecione o mentor</option>{mentors.data?.map(m => <option value={m.id} key={m.id}>{m.name} · {m.activeClients}/{m.capacity} clientes</option>)}</select></Field>{kind === 'coverage' && <Field label="Fim da cobertura (horário deste dispositivo)"><input name="endsAt" type="datetime-local" required /></Field>}<p className="form-note">A alteração atualiza os acessos imediatamente. Prazos existentes e a autoria das mensagens são preservados.</p><ErrorBox error={error || mentors.error} /><div className="dialog-actions"><Button type="button" variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={busy}>Salvar atribuição</Button></div></form></Dialog>;
}

function Mentors() {
  const query = useQuery({ queryKey: ['mentors'], queryFn: () => api<Mentor[]>('/mentors') });
  return <><PageTitle eyebrow="CUIDAR DE QUEM ACOMPANHA" title="Equipe de mentores" description="Distribua a carteira com contexto e respeite a capacidade de cada pessoa." /><ErrorBox error={query.error} />{query.isPending ? <Loading /> : <div className="mentor-grid">{query.data?.map(m => <section className="panel mentor-card" key={m.id}><div className="mentor-profile"><Avatar name={m.name} /><div><h2>{m.name}</h2><p>{m.email}</p></div></div><div className="capacity-title"><span>Carteira ativa</span><strong>{m.activeClients} <small>/ {m.capacity} clientes</small></strong></div><div className="capacity-track"><span className={m.activeClients > m.capacity ? 'over' : ''} style={{ width: `${Math.min(100, m.capacity ? m.activeClients / m.capacity * 100 : 0)}%` }} /></div><Badge tone={m.activeClients > m.capacity ? 'red' : m.activeClients === m.capacity ? 'amber' : 'green'}>{m.activeClients > m.capacity ? 'Acima da capacidade' : m.activeClients === m.capacity ? 'Capacidade preenchida' : `${m.capacity - m.activeClients} vagas na carteira`}</Badge><p className="mentor-context">A capacidade é uma referência de distribuição. Considere complexidade, ausências e qualidade ao atribuir clientes.</p></section>)}{!query.data?.length && <Empty title="Nenhum mentor cadastrado" detail="Os mentores ativos da organização aparecerão aqui." />}</div>}</>;
}

function Notifications({ data, error, loading, go, notify }: { data?: Notification[]; error: unknown; loading: boolean; go: (to: string) => void; notify: (message: string) => void }) {
  const [filter, setFilter] = useState('unread'); const [busy, setBusy] = useState(''); const queryClient = useQueryClient();
  const alertsMotion = useMotionRegion(filter);
  const filtered = (data || []).filter(n => filter === 'all' || !n.acknowledgedAt);
  async function ack(id: string) { setBusy(id); try { await post(`/notifications/${id}/ack`, {}); await queryClient.invalidateQueries({ queryKey: ['notifications'] }); notify('Ciência registrada.'); } catch (err) { notify(err instanceof Error ? err.message : 'Não foi possível registrar ciência.'); } finally { setBusy(''); } }
  return <><PageTitle eyebrow="SINAIS QUE VIRAM AÇÃO" title="Central de alertas" description="Prazos e acompanhamentos que precisam de uma decisão." /><section ref={alertsMotion} className="panel"><div className="tabs"><button className={filter === 'unread' ? 'selected' : ''} onClick={() => setFilter('unread')}>Pendentes de ciência</button><button className={filter === 'all' ? 'selected' : ''} onClick={() => setFilter('all')}>Todos os alertas</button></div><ErrorBox error={error} />{loading ? <Loading /> : filtered.length ? <div>{filtered.map(n => <div className={`notification-row ${n.acknowledgedAt ? 'read' : ''}`} key={n.id}><span className="notification-icon"><Bell size={18} /></span><div><h3>{n.title}</h3><p>{n.body}</p><small>{fmtTime(n.createdAt)}{n.acknowledgedAt ? ` · Ciência em ${fmtTime(n.acknowledgedAt)}` : ''}</small><div className="notification-actions">{n.diagnosisId && <button className="text-button" onClick={() => go(`/diagnoses/${n.diagnosisId}`)}>Abrir diagnóstico <ArrowRight size={13} /></button>}{n.meetingId && <button className="text-button" onClick={() => go(`/meetings/${n.meetingId}`)}>Abrir reunião <ArrowRight size={13} /></button>}{n.taskId && <button className="text-button" onClick={() => go(`/tasks/${n.taskId}`)}>Abrir tarefa <ArrowRight size={13} /></button>}{n.planId && !n.taskId && <button className="text-button" onClick={() => go(`/plans/${n.planId}`)}>Abrir plano <ArrowRight size={13} /></button>}{n.ticketId && <button className="text-button" onClick={() => go(`/tickets/${n.ticketId}`)}>Abrir atendimento <ArrowRight size={13} /></button>}{n.actionUrl && /^\/meetings(?:\/|\?|$)/.test(n.actionUrl) && !n.meetingId && <button className="text-button" onClick={() => go(n.actionUrl!)}>Abrir agenda <ArrowRight size={13} /></button>}{!n.acknowledgedAt && <button className="text-button" onClick={() => ack(n.id)} disabled={busy === n.id}><Check size={14} />Registrar ciência</button>}</div></div></div>)}</div> : <Empty title="Tudo lido por aqui" detail="Novos avisos de acompanhamento e prazo aparecerão nesta central." />}</section></>;
}
